// Builds web/sample-bundle.js: analysis.json + source documents embedded as JS, so the
// dashboard also works when web/index.html is opened directly from disk (file://).
// Usage: npm run bundle   (re-run after editing analysis.json or sample documents)
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const analysis = JSON.parse(fs.readFileSync(path.join(ROOT, 'analysis.json'), 'utf8'));
const docs = {};
for (const d of analysis.meta.documents) docs[d.id] = fs.readFileSync(path.join(ROOT, d.file), 'utf8');
const out = `// GENERATED by scripts/bundle.js - do not edit. Offline fallback for file:// use.\nwindow.PERMITPILOT_BUNDLE = ${JSON.stringify({ analysis, docs })};\n`;
fs.writeFileSync(path.join(ROOT, 'web', 'sample-bundle.js'), out);
console.log(`Wrote web/sample-bundle.js (${Object.keys(docs).length} documents, ${(out.length / 1024).toFixed(0)} KB)`);
